(function(r,f){const m=f();if(typeof module==='object')module.exports=m;else r.Model=m})(globalThis,()=>{'use strict';const KEY='ob.readingList.v1';function url(s){if(typeof s!=='string'||s.length>2048||/[\u0000-\u0020\u007f]/.test(s))throw Error('Enter a complete HTTP or HTTPS address.');const u=new URL(s);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Only public web addresses without embedded credentials are allowed.');return u.href}function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!Array.isArray(s.items)||s.items.length>200)throw Error('Saved list is invalid.');const ids=new Set();for(const x of s.items){if(typeof x.id!=='string'||!/^[a-zA-Z0-9_-]{1,64}$/.test(x.id)||ids.has(x.id)||typeof x.title!=='string'||!x.title.trim()||x.title.length>120||url(x.url)!==x.url||!['page','video'].includes(x.kind)||typeof x.done!=='boolean')throw Error('Saved item is invalid.');ids.add(x.id)}return structuredClone(s)}function empty(){return{version:1,revision:0,items:[]}}function change(state,op){const s=validate(state);if(op.type==='add'){if(op.private)throw Error('Leave private browsing before saving to the shared list.');const u=url(op.url),title=String(op.title||'').trim();if(!title||title.length>120)throw Error('Use a title of 1–120 characters.');if(!['page','video'].includes(op.kind))throw Error('Invalid item type.');if(s.items.some(x=>x.url===u))throw Error('This address is already saved.');if(s.items.length>=200)throw Error('Your list is full (200 items).');s.items.unshift({id:op.id,title,url:u,kind:op.kind,done:false})}else{const i=s.items.findIndex(x=>x.id===op.id);if(i<0)throw Error('Item no longer exists.');if(op.type==='remove')s.items.splice(i,1);else if(op.type==='toggle')s.items[i].done=!s.items[i].done;else throw Error('Unknown action.')}s.revision++;return validate(s)}function load(storage){const raw=storage.getItem(KEY);if(raw&&raw.length>500000)throw Error('Saved list exceeds its limit.');return raw?validate(JSON.parse(raw)):empty()}function commit(storage,previous,next){if(load(storage).revision!==previous.revision)throw Error('List changed in another view. Reload before saving.');storage.setItem(KEY,JSON.stringify(validate(next)));return next}function projection(s){return validate(s).items.filter(x=>!x.done).slice(0,6)}return{KEY,url,validate,empty,change,load,commit,projection}});
